const API = "https://corsproxy.io/?url=https://studio.code.org/v3/channels/"; //https://fetch-proxy.jacobbutler6.repl.co/json?url=
const projectTable = document.querySelector("#projectList");
projectTable.innerHtml = "";
const pages = {};
const projectsPerPage = 30;
const maxPage = (ids.length - 1) / projectsPerPage;
const previous = document.querySelector("#previous");
const pageCounter = document.querySelector("#counter");
const next = document.querySelector("#next");
let currentPage = 1;
// Loop through the projects array and create table rows with thumbnails
function pageParser(index) {
    let source = ids[index];
    fetch(API + source)
        .then(response => {
            if (response.status < 206) {
                return (response.json())
            }
        })
        .then(project => {
            if (project == undefined) { return }
            let date = new Date(project.updatedAt);
            const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
            const entry = document.createElement("tr");
            entry.innerHTML = `
       <th>
        <a href=${location.pathname}project?url=https://studio.code.org${project.level}/${source}>
         <img class=project-thumbnail src=https://corsproxy.io?url=https://studio.code.org${project.thumbnailUrl} alt=${project.name}_Thumbnail loading=lazy></img>
        </a>
       </th>
       <th>
        <a href=https://studio.code.org${project.level}/${source}>
         <h2> ${project.name} </h2>
        </a>
       </th>
       <th>
        <h3> ${project.projectType} </h3>
       </th>
       <th>
        <p> ${monthNames[date.getMonth()]} ${date.getDate()}, ${date.getFullYear()} <p>
      `
            projectTable.appendChild(entry);
        })
        .catch(err => {
            console.log(err);
        })
        .finally(() => {
            if (index < ids.length - 1) {
                orderedFetch(index + 1);
            }
        })
}

function filterProjects(e) {
    let filter = e.srcElement.innerText.toLowerCase().replace(/\s/g, "") || e.srcElement.parentElement.innerText.toLowerCase().replace(/\s/g, "");
    let pjs = Array.from(document.querySelector("#projectList").children);
    let pjdata = Array();
    let filteredProjects = Array();

    if (filter === "name") {

        pjs.forEach(d => pjdata.push(d.children[1].innerText.toLowerCase()));
        pjdata.sort();

        pjdata.forEach(p => {
            let project = pjs.filter(d => { return p == d.children[1].innerText.toLowerCase() });
            filteredProjects.push(project[0].outerHTML);
        })

    }

    if (filter === "type") {
        pjs.forEach(d => {
            pjdata.push({ element: d, type: d.children[2].innerText.toLowerCase() });
        })
        pjdata.sort(function (a, b) { return b.type < a.type });
        pjdata.forEach(p => {
            filteredProjects.push(p.element.outerHTML);
        })
    }

    if (filter === "lastupdated") {
        //pjs.sort(function(a, b){return b-a});
        pjs.forEach(e => {
            pjdata.push({ element: e, date: (new Date(e.children[3].innerText.toLowerCase())).getTime() })
        })
        pjdata.sort(function (a, b) { return b.date - a.date })
        pjdata.forEach(d => {
            filteredProjects.push(d.element.outerHTML)
        })
    }
    filteredProjects = filteredProjects.join("");
    document.querySelector("#projectList").innerHTML = filteredProjects;

    document.querySelectorAll(".filterable").forEach(d => {
        if (filter === d.innerText.toLowerCase().replace(/\s/g, "")) d.children[0].classList.remove("right"), d.children[0].classList.add("down")
        else d.children[0].classList.remove("down"), d.children[0].classList.add("right")
    })

}

function searchAll() {
    let searchBy = document.querySelector("#searchby").selectedIndex;
    let search = new RegExp(document.querySelector("#search").value, "gi");
    let projects = Array.from(document.querySelector("#projectList").children)
    projects.forEach(p => {
        let column = p.children;
        let content = column[searchBy].innerText;
        if (search.test(content) || searchBy < 1) {
            p.style.display = "table-row";
        } else {
            p.style.display = "none";
        }
    })
}

document.querySelectorAll(".filterable").forEach(d => {
    d.onclick = filterProjects;
})

if (currentPage === null) { currentPage = 1; }
else { currentPage = parseInt(currentPage[1]); }

function searchIndex(pageNumber) {
    const params = new URLSearchParams(location.search);
    const id = params.get("query") ? "QUERY:" + params.get("query") : "SORT:" + params.get("sort");
    let cachePage = pages[id] = pages[id] || { [cacheType]: [] };
    currentPage = pageNumber || currentPage;
    projectTable.innerHTML = '';

    mainIndex(true).then(posts => {
        posts.forEach(post => pageParser(projectTable, tok)(post));
        checkArrows();
    });

    previous.onclick = async e => await changePage(e, -1);

    next.onclick = async e => await changePage(e, 1);

    async function mainIndex(omitState) {
        let params = new URLSearchParams(location.search);
        let page = currentPage;
        if (!omitState) { params.set("page", currentPage); }
        else if (!Number.isSafeInteger(parseInt(params.get("page")))) { params.set("page", currentPage); }
        history.replaceState({}, "", buildUrl(params));
        if (cachePage[cacheType][page - 1] === undefined) {
            const data = ids.slice((page-1)*30,page*30);
            cachePage.length = data.length;
            cachePage[cacheType][page - 1] = data[cacheType];
        }
        if (!params.get("total")) {
            params.set("total", cachePage.length);
            history.replaceState({}, "", buildUrl(params));
        }
        return page === currentPage ? cachePage[cacheType][page - 1] : [];
    }

    function checkArrows() {
        if ((currentPage + 1) > maxPage) { next.style.visibility = "hidden"; }
        else { next.style.visibility = ""; }
        pageCounter.textContent = `${currentPage} / ${maxPage}`;
        if ((currentPage - 1) < 1) { previous.style.visibility = "hidden"; }
        else { previous.style.visibility = ""; }
    }

    function changePage(e, amount) {
        e.preventDefault();
        projectTable.innerHTML = '';
        currentPage += amount;
        checkArrows();
        let posts = mainIndex();
        posts.forEach(post => pageParser(post));
    }

    window.onpopstate = async () => {
        let params = new URLSearchParams(location.search);
        let page = parseInt(params.get("page")) || 1;
        let oldCache = cachePage;
        cachePage = pages[(params.get("query") ? "QUERY:" + params.get("query") : "SORT:" + params.get("sort"))];
        if (page !== currentPage || oldCache !== cachePage) {
            projectTable.innerHTML = '';
            currentPage = page;
            let projectPage = mainIndex(true);
            checkArrows();
            projectPage.forEach(proj => pageParser(projectTable, tok)(proj));
        }
    }
}

function buildUrl(params) {
    const url = new URL(window.location);
    url.search = new URLSearchParams(params).toString();
    return url;
}
searchIndex()
document.querySelector("#search").onchange = searchAll;
document.querySelector("#searchby").onchange = searchAll;